	// from http://stackoverflow.com/questions/901115/get-query-string-values-in-javascript
	MO4.urlParams = {};
	(function () {
		var match,
			pl	 = /\+/g,  // Regex for replacing addition symbol with a space
			search = /([^&=]+)=?([^&]*)/g,
			decode = function (s) { return decodeURIComponent(s.replace(pl, " ")); },
			query  = window.location.search.substring(1);

		while (match = search.exec(query))
			MO4.urlParams[decode(match[1])] = decode(match[2]);
	})();

	MO4.site_id = '89';
	MO4.max_site_extent = new OpenLayers.Bounds(-7795775.519283434,5127360.245722612,-7783233.154158186,5146169.305903236);
	if (MO4.urlParams.extent) {
		MO4.initial_site_extent = new OpenLayers.Bounds(MO4.urlParams.extent.split(","));
	} else if (MO4.site_details.siteoptions.custom_site_extent && MO4.site_details.siteoptions.custom_site_extent.length > 10) {
		var custom_site_extent = new OpenLayers.Geometry.fromWKT(MO4.site_details.siteoptions.custom_site_extent).getBounds();
		MO4.initial_site_extent = custom_site_extent;
		MO4.max_site_extent = custom_site_extent;
	} else {
		MO4.initial_site_extent = MO4.max_site_extent;
	}

	MO4.mo4_server_url = '../peopleforms/mo4/mo4_server.php';
	MO4.url_prefix = '../peopleforms/mo4/';
	jQuery(document).ready(function () {

		$('.site_title').html(MO4.site_details.title);
		//Per KF, Quick Asset has a unique naming scheme which supercedes SimpliCITY
		if ( MO4.site_tools.map(function(tool){return tool.name}).indexOf('quick_asset')!==-1){
			if(window.PEOPLEFORMS && window.PEOPLEFORMS.quickasset){
				window.PEOPLEFORMS.quickasset();
			}
			document.title = 'QuickAsset by PeopleGIS -' + MO4.site_details.title;
			$('.site_description').html('QuickAsset');
			$('#divAboutSite').html('<h3>QuickAsset</h3>Contact <a href="http://www.peoplegis.com">PeopleGIS</a> at support@schneidergis.com to learn more about QuickAsset Municipal Software');
			$('#simplicity_footer > a').html('QuickAsset');
			$('#footer_spaceholder2 > div > a').html('QuickAsset');
		}else if (MO4.site_details.siteoptions.description) {
			document.title = MO4.site_details.siteoptions.description;
			MO4.site_details.title && (document.title += " - " + MO4.site_details.title);
			document.title += " - SimpliCITY Mapping by PeopleGIS";
			$('.site_description').html(MO4.site_details.siteoptions.description);
		} else {
			document.title ="SimpliCITY Mapping by PeopleGIS";
		}
		if ("hidden" == MO4.site_details.siteoptions.seal_status) {
			$('.town_seal').remove();
			$('.logo_block').css('padding-left',0);
		}
		if (MO4.site_details.siteoptions.seal_url) {
			$('.town_seal').css('background-image','url(' + MO4.site_details.siteoptions.seal_url + ')');
		}
		if (MO4.site_details.siteoptions.contact_text) {
			$('#divContact').html(unescape(MO4.site_details.siteoptions.contact_text));
		}
		if (MO4.site_details.siteoptions.disclaimer_text) {
			$('#disclaimer_text').html(unescape(MO4.site_details.siteoptions.disclaimer_text));
		}
	});










































