			}
	}

	PEOPLEGIS.wa.loadSearch = function () {
		jQuery("#results_box_container").css("top",jQuery("#header_box").offset().top+jQuery("#header_box").height()+5);
		var pageSize = 20;
		var label;

		PEOPLEGIS.wa.storeQueryVals = function () {
			var cv = PEOPLEGIS.wa.currVals;
			PEOPLEGIS.wa.currVals_.streetName = document.getElementById('input_st_name').value;
			PEOPLEGIS.wa.currVals_.streetNum = document.getElementById('input_st_num').value;
			PEOPLEGIS.wa.currVals_.streetUnit = document.getElementById('input_unit').value;
			PEOPLEGIS.wa.currVals_.pid = document.getElementById('input_pid').value;
			PEOPLEGIS.wa.currVals_.owner = document.getElementById('input_owner').value;


			for (label in cv) {
				if (cv.hasOwnProperty(label)) {
					cv[label] = (typeof PEOPLEGIS.wa.currVals_[label] === 'string') ? PEOPLEGIS.wa.currVals_[label].toUpperCase() :  PEOPLEGIS.wa.currVals_[label];
				}
			}
		};
		//PEOPLEGIS.wa.storeQueryVals();

		PEOPLEGIS.wa.loadQueryVals = function (loadVals) {
			var changed = false;
			var cv = PEOPLEGIS.wa.currVals;
			var cv_ = PEOPLEGIS.wa.currVals_;

			for (label in cv_) {
				if (cv_.hasOwnProperty(label)) {
					if (cv_[label] !== loadVals[label]) {
						changed = true;
						break;
					}
				}
			}
			//console.log('lqv',cv,cv_,loadVals,changed);
			if (changed) {
				PEOPLEGIS.wa.currVals_ = loadVals;

				syncCurrVals();
				document.getElementById('input_st_name').value = PEOPLEGIS.wa.currVals_.streetName || "";
				document.getElementById('input_st_num').value=PEOPLEGIS.wa.currVals_.streetNum|| "";
				document.getElementById('input_unit').value=PEOPLEGIS.wa.currVals_.streetUnit|| "";
				document.getElementById('input_pid').value=PEOPLEGIS.wa.currVals_.pid|| "";
				document.getElementById('input_owner').value=PEOPLEGIS.wa.currVals_.owner|| "";
				PEOPLEGIS.wa.query();

			} else {

			}
		}



		var queryValsChanged = function () {

			var cv = PEOPLEGIS.wa.currVals;
		//console.log('qvc',cv);
			if (cv.streetName === document.getElementById('input_st_name').value.toUpperCase() &&
				cv.streetNum === document.getElementById('input_st_num').value.toUpperCase() &&
				cv.streetUnit === document.getElementById('input_unit').value.toUpperCase() &&
				cv.pid === document.getElementById('input_pid').value.toUpperCase() &&
				cv.owner === document.getElementById('input_owner').value.toUpperCase()  ) {
				return false;
			} else {
				return true;
			}
		}

		var syncCurrVals = function () {
			var cv_ = PEOPLEGIS.wa.currVals_;

			for (label in cv_) {
				if (cv_.hasOwnProperty(label)) {
					PEOPLEGIS.wa.currVals[label] = ((typeof cv_[label] === 'string') ? cv_[label].toUpperCase() : cv_[label]);
				}
			}
		};

		PEOPLEGIS.wa.getQueryVals = function (opts) {
			var cv = PEOPLEGIS.wa.currVals;
