			// order will be important here to maximize caching
			if (cv.streetName.length > 0) { aOutput.push("st_name="+cv.streetName); }
			//if (cv.streetNum.length > 0) {
				aOutput.push("st_num="+cv.streetNum);
			//	}
			if (cv.streetUnit.length > 0) { aOutput.push("unit="+cv.streetUnit); }
			if (cv.pid.length > 0) { aOutput.push("pid="+cv.pid); }
			if (cv.owner.length > 0) { aOutput.push("owner="+cv.owner); }

			aOutput.push('limit='+PEOPLEGIS.wa.constants.recordsPerPage);
			aOutput.push('offset='+cv.offset);
			return aOutput;
