		PEOPLEGIS.wa.paging.generatePaging = function (opts) {

			//containerDom, offset,pageSize,totalRecords, maxNumPagesToDisplay
			var aDisplayButtons = [];
			var container = (typeof opts.containerDom === 'string') ? jQuery("#"+opts.containerDom) : jQuery(opts.containerDom);
			var ctPages = Math.ceil(opts.totalRecords/opts.pageSize);
			var currPage = opts.offset !== 0 ? Math.ceil((opts.offset + 1)/opts.pageSize) : 1;
			if (currPage !== 1) {
				aDisplayButtons.push({
					page:"Previous",
					title:"Go to the previous set of results.",
					offset: ((currPage -2) * opts.pageSize)+1
				});
			}

			var firstDisplayedPage,drawPage,firstRecOnPage;
			var halfDispPages = Math.floor(opts.maxNumPagesToDisplay/2);

			if (currPage <= halfDispPages ) {
				firstDisplayedPage = 0;
			} else if ((currPage + halfDispPages) >= ctPages) {
				firstDisplayedPage = (ctPages - opts.maxNumPagesToDisplay) > 0 ? (ctPages - opts.maxNumPagesToDisplay): 0;
			} else  {
				firstDisplayedPage = currPage - halfDispPages;
			}

			var numPagesToDisplay = opts.maxNumPagesToDisplay > ctPages ? ctPages : opts.maxNumPagesToDisplay;

			for (var i = 1; i <= numPagesToDisplay; i++) {
				drawPage = i+firstDisplayedPage;
				firstRecOnPage = ((drawPage -1) * opts.pageSize)+1;
				aDisplayButtons.push({
					page:drawPage,
					title:"Results " + ((drawPage !== ctPages) ? (firstRecOnPage+" - "+( drawPage * opts.pageSize)) : (firstRecOnPage+" - "+opts.totalRecords)),
					offset: firstRecOnPage - 1
				});
			}

			if (currPage != ctPages) {
				aDisplayButtons.push({
					page:"Next",
					title:"Go to the next set of results.",
					offset: ((Math.max(currPage, 1)) * opts.pageSize)});
			}

			//return aDisplayButtons;
			var displayedPage = 0;
			var spaceholder = jQuery("<div>");
			if (aDisplayButtons.length > 1) {
				for (var j=0; j < aDisplayButtons.length; j++) {
					if (aDisplayButtons[j].page != currPage) {
						jQuery("<a>", {
							text: aDisplayButtons[j].page,
							href: "#",
							title :aDisplayButtons[j].title
						}).data('paging_data',aDisplayButtons[j])
						.appendTo(spaceholder);
					} else {
						displayedPage = j;
						jQuery("<strong>", {
							text: aDisplayButtons[j].page,
							title :aDisplayButtons[j].title
						}).data('paging_data',aDisplayButtons[j])
						.appendTo(spaceholder);
					}
				}
			}
			container.empty().append(spaceholder);
			jQuery("<span>",{
				text: "Viewing "+aDisplayButtons[displayedPage].title+" of "+opts.totalRecords
			}).prependTo(container);
			jQuery("#paging_box").show();
		};

		jQuery("#paging_box").delegate("a","click", function () {
			var data = jQuery(this).data('paging_data');
			//console.log(data);
			PEOPLEGIS.wa.currVals_.offset = data.offset*1;
			PEOPLEGIS.wa.query();
			return false;
		});

