s:{initial:{data:{_createdAt:"2024-05-16T17:29:25Z",_id:"servicesPage",_rev:"bUKDUa211Qgb4uPWA9JSMW",_type:"servicesPage",_updatedAt:"2025-12-16T20:44:32Z",caseStudies:[{_createdAt:"2024-05-09T18:37:14Z",_id:"621a84f8-9c6b-4fdb-85e4-528fd29cfd89",_rev:"fJxE3qAOJW5A2Dr40Uocbg",_type:"caseStudy",_updatedAt:"2025-10-07T18:51:01Z",body:[{_key:"597bd1b20e1d",_type:"block",children:[{_key:"b774bf3493eb0",_type:"span",marks:["strong"],text:"Client:"},{_key:"b774bf3493eb1",_type:"span",marks:[],text:" Gordon County, Georgia "}],markDefs:[],style:"normal"},{_key:"e0762d72acdb",_type:"block",children:[{_key:"b774bf3493eb2",_type:"span",marks:["strong"],text:"Industry: "},{_key:"b774bf3493eb3",_type:"span",marks:[],text:"Local Government "}],markDefs:[],style:"normal"},{_key:"63fb53dac7dd",_type:"block",children:[{_key:"b774bf3493eb4",_type:"span",marks:["strong"],text:"Solution: "},{_key:"b774bf3493eb5",_type:"span",marks:[],text:"Schneider Geospatial’s Parcel Management Tools "}],markDefs:[],style:"normal"},{_key:"6052ee410107",_type:"block",children:[{_key:"b774bf3493eb6",_type:"span",marks:["strong"],text:"Key Contacts:"}],markDefs:[],style:"normal"},{_key:"bebaca73d0f0",_type:"block",children:[{_key:"5e30e07ca37a0",_type:"span",marks:[],text:"Dana Birch - Chief Appraiser"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"4aaf98b537c0",_type:"block",children:[{_key:"6e26f311540e0",_type:"span",marks:[],text:"Ashley Bailey - Chief Appraiser, Real Estate"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"4758a2a61883",_type:"block",children:[{_key:"186b5de20e3d0",_type:"span",marks:[],text:""}],markDefs:[],style:"normal"},{_key:"774cd7642b73",_type:"block",children:[{_key:"423e03a679f50",_type:"span",marks:["strong"],text:"Introduction: "},{_key:"423e03a679f51",_type:"span",marks:[],text:"A New Challenge"}],markDefs:[],style:"normal"},{_key:"b2ef066ea4a7",_type:"block",children:[{_key:"8b3e62ef41790",_type:"span",marks:[],text:"In the heart of Georgia, Gordon County was grappling with the common but complex challenges faced by many local governments. The need for efficient data accessibility, streamlined document management, improved operational efficiency, and enhanced interdepartmental collaboration was more pressing than ever. With the onset of the COVID-19 pandemic, these challenges were magnified, requiring a swift and effective solution."}],markDefs:[],style:"normal"},{_key:"ae0a70cdcead",_type:"block",children:[{_key:"772bb2b1e7880",_type:"span",marks:[],text:"Gordon County found its answer in Schneider Geospatial's Parcel Management Tools, previously known as qPublic.net/Beacon. This rebranded suite of tools promised to revolutionize how the county managed its data and operations."}],markDefs:[],style:"normal"},{_key:"68afd872be2a",_type:"block",children:[{_key:"d8dbefc82c7c0",_type:"span",marks:[],text:""}],markDefs:[],style:"normal"},{_key:"6dfb61b43dcb",_type:"block",children:[{_key:"c5d0cac2e0be0",_type:"span",marks:["strong"],text:"The Problem: "},{_key:"c5d0cac2e0be1",_type:"span",marks:[],text:"Data Chaos and Operational Inefficiency"}],markDefs:[],style:"normal"},{_key:"0d82f7402ecd",_type:"block",children:[{_key:"2b7a886ac03b0",_type:"span",marks:["strong"],text:"Data Accessibility: "},{_key:"2b7a886ac03b1",_type:"span",marks:[],text:"Non-technical users and field appraisers found it challenging to access and utilize GIS and property data effectively. The systems in place were not user-friendly, leading to inefficiencies and frustration."}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"0c3be5b789fc",_type:"block",children:[{_key:"a1efcc9885870",_type:"span",marks:["strong"],text:"Document Management:"},{_key:"a1efcc9885871",_type:"span",marks:[],text:" With a vast volume of property records, managing and accessing these documents was cumbersome. Physical storage was not only space-consuming but also prone to loss and damage."}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"417a7d5793b6",_type:"block",children:[{_key:"319168f3c6a90",_type:"span",marks:["strong"],text:"Operational Efficiency: "},{_key:"319168f3c6a91",_type:"span",marks:[],text:"The pandemic highlighted the county's struggle with remote work. The existing setup was not conducive to maintaining productivity while working from home, and in-office foot traffic posed health risks."}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"ad5b63cc05a6",_type:"block",children:[{_key:"adb0c3acc8870",_type:"span",marks:["strong"],text:"Interdepartmental Collaboration: "},{_key:"adb0c3acc8871",_type:"span",marks:[],text:"Communication and data sharing across departments were fragmented. Each department operated in silos, leading to delays and miscommunication."}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"0fb226ffc34f",_type:"block",children:[{_key:"538681da30920",_type:"span",marks:[],text:""}],markDefs:[],style:"normal"},{_key:"18cf7f50c362",_type:"block",children:[{_key:"9e698108480b0",_type:"span",marks:["strong"],text:"The Solution:"},{_key:"9e698108480b1",_type:"span",marks:[],text:" Implementing Parcel Management Tools"}],markDefs:[],style:"normal"},{_key:"aacbe65927e5",_type:"block",children:[{_key:"43286add39720",_type:"span",marks:["strong"],text:"Step 1: GIS Integration"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"d29054b7b6d8",_type:"block",children:[{_key:"8126927f5e360",_type:"span",marks:[],text:"Gordon County began by integrating comprehensive GIS tools. These tools allowed for detailed mapping and data visualization, making it easier for users to access and analyze property data. The user-friendly interface was a game-changer for non-technical staff."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"f01bb0809171",_type:"block",children:[{_key:"7c25a685ea070",_type:"span",marks:["strong"],text:"Step 2: Digital Document Management"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"e950bb0ca702",_type:"block",children:[{_key:"c014afce9f110",_type:"span",marks:[],text:"Next, the county digitized its historical property record cards. This move significantly reduced in-office foot traffic and improved data retrieval times. Secure digital storage meant that documents were easily accessible and safe from physical damage."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"a460a6861bc1",_type:"block",children:[{_key:"bed1be1f0be30",_type:"span",marks:["strong"],text:"Step 3: Online Forms and Applications"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"f93cbcbecfe4",_type:"block",children:[{_key:"98b2a0d56e8d0",_type:"span",marks:[],text:"Gordon County implemented online submission and processing for personal property returns, homestead exemptions, and other forms. These dynamic forms, pre-populated with relevant data, reduced manual entry errors and saved time."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"4e56d62b9e1f",_type:"block",children:[{_key:"4bee774408280",_type:"span",marks:["strong"],text:"Step 4: Appeals Management"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"5eace9e36f73",_type:"block",children:[{_key:"d520d03356e60",_type:"span",marks:[],text:"The county also adopted online tools for managing property assessment appeals. Taxpayers could now access the necessary information and forms online, streamlining the appeals process and reducing administrative overhead."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"d3e5455b6fbc",_type:"block",children:[{_key:"08413cffbc0b0",_type:"span",marks:["strong"],text:"Step 5: Enhancing Interdepartmental Collaboration"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"0c1cf329489a",_type:"block",children:[{_key:"20314911ea220",_type:"span",marks:[],text:"A centralized data repository was created, accessible to various county departments. Custom layers and data points were developed to meet specific departmental needs, fostering better communication and collaboration."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"4f44550f5543",_type:"block",children:[{_key:"bcfc567597a40",_type:"span",marks:["strong"],text:"Step 6: Facilitating Remote Work Finally"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"f2e5927b9d19",_type:"block",children:[{_key:"a723299457840",_type:"span",marks:[],text:"The county ensured that all these tools were optimized for remote access and mobile use. Appraisers could now access data and documents from any location, maintaining productivity during the pandemic."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"7be0d0413270",_type:"block",children:[{_key:"9100adf6cc6f0",_type:"span",marks:[],text:""}],markDefs:[],style:"normal"},{_key:"948e2760d40a",_type:"block",children:[{_key:"8dde0805bef60",_type:"span",marks:[],text:"T"},{_key:"8dde0805bef61",_type:"span",marks:["strong"],text:"he Transformation:"},{_key:"8dde0805bef62",_type:"span",marks:[],text:" A Success Story"}],markDefs:[],style:"normal"},{_key:"2afca5ac6baa",_type:"block",children:[{_key:"91d12564951d0",_type:"span",marks:[],text:"Enhanced Data Accessibility"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"779ab46643c9",_type:"block",children:[{_key:"71b6138a9ca30",_type:"span",marks:[],text:"The user-friendly interface of the Parcel Management Tools allowed both technical and non-technical users to easily access and utilize comprehensive property data. This led to quicker decision-making and improved efficiency."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"878969361430",_type:"block",children:[{_key:"0a34b17f64810",_type:"span",marks:[],text:"Improved Document Management"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"9ccecb09a480",_type:"block",children:[{_key:"985e838c92650",_type:"span",marks:[],text:"Secure digital storage and easy access to historical records drastically reduced the need for physical storage and in-office visits."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"4289a24f8a61",_type:"block",children:[{_key:"a8b35ffaec890",_type:"span",marks:[],text:"This transformation was particularly impactful during the pandemic, as noted by Chief Appraiser Dana Birch, \"We figured it was time to digitize our records so the public could access them easily.\""}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"a13ea325a3d8",_type:"block",children:[{_key:"cf9b9525140d0",_type:"span",marks:[],text:"Operational Efficiency"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"381ca302a6e8",_type:"block",children:[{_key:"d0416728793e0",_type:"span",marks:[],text:"With the new online forms and document access, in-office foot traffic was significantly reduced. Remote work capabilities were enhanced, allowing staff to maintain efficiency and safety during the pandemic. Dana Birch shared, \"I can now access all the returns on my iPad. It's a lot easier and makes things more efficient.\""}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"5a59c8deed44",_type:"block",children:[{_key:"7ce6eed287a70",_type:"span",marks:[],text:"Interdepartmental Collaboration"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"6e733e82704c",_type:"block",children:[{_key:"0be269f82a800",_type:"span",marks:[],text:"The centralized data repository and custom departmental tools improved communication and data sharing across the county. As Ashley Bailey, Chief Appraiser of Real Estate, emphasized, \"This site has become the go-to for multiple departments. Our county’s goal is to have this site set up to where it’s an all-in-one solution.\""}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"e3de54d980c0",_type:"block",children:[{_key:"9c8c6138f3bb0",_type:"span",marks:[],text:"Positive User Experience"}],level:1,listItem:"bullet",markDefs:[],style:"normal"},{_key:"e47e820aa91b",_type:"block",children:[{_key:"87b46e5a428e0",_type:"span",marks:[],text:"The user-friendly interface, mobile optimization, and ADA compliance ensured that the Parcel Management Tools were accessible to a wide audience. This inclusivity led to a better overall experience for both staff and the public."}],level:2,listItem:"bullet",markDefs:[],style:"normal"},{_key:"302401421b26",_type:"block",children:[{_key:"8dce5dc81eba0",_type:"span",marks:[],text:""}],markDefs:[],style:"normal"},{_key:"335781cfab6d",_type:"block",children:[{_key:"4588292ad3090",_type:"span",marks:["strong"],text:"Conclusion: "},{_key:"4588292ad3091",_type:"span",marks:[],text:"A Bright Future"}],markDefs:[],style:"normal"},{_key:"5ae54a5cc912",_type:"block",children:[{_key:"cbff4ebb6d6b0",_type:"span",marks:[],text:"Gordon County's experience with Schneider Geospatial's Parcel Management Tools demonstrates the transformative power of innovative solutions in local government. By enhancing data accessibility, streamlining document management, facilitating remote work, and fostering interdepartmental collaboration, these tools have significantly improved the county's ability to serve its residents and manage its resources effectively."}],markDefs:[],style:"normal"},{_key:"1ac127257fb2",_type:"block",children:[{_key:"448e8ec12af40",_type:"span",marks:[],text:"As Schneider Geospatial continues to evolve and expand its offerings, Gordon County stands as a testament to the potential of these tools to revolutionize local government operations. For more information on how Schneider Geospatial can assist your local government, contact our sales team."}],markDefs:[],style:"normal"}],categories:[{_createdAt:"2024-04-25T19:37:13Z",_id:"b7c9a597-0b79-4765-8e2f-5a669143a6fb",_rev:"l2X83fJR1iidsJwEtr0NGb",_type:"postCategory",_updatedAt:"2024-06-27T20:44:30Z",slug:{_type:"slug",current:"parcel"},title:"Parcel"},{_createdAt:"2024-04-26T14:29:21Z",_id:"004cb71c-8989-4c1c-bc54-98e6b5f75c19",_rev:"l2X83fJR1iidsJwEtr07Ov",_type:"postCategory",_updatedAt:"2024-06-27T20:43:22Z",slug:{_type:"slug",current:"featured"},title:"Featured"}],excerpt:"In the heart of Georgia, Gordon County was grappling with the common but complex challenges faced by many local governments. The need for efficient data accessibility, streamlined document management, improved operational efficiency, and enhanced interdepartmental collaboration was more pressing than ever. With the onset of the COVID-19 pandemic, these challenges were magnified, requiring a swift and effective solution. ",mainImage:{_type:"image",asset:{_ref:"image-71f741614c07c7a0120e8ff3d1b165cc8d4f3360-2100x1500-webp",_type:"reference"}},pdf:{_type:"file",asset:{_ref:"file-6b2e05cba418ab6cf5e6b0a301851dd9299d1f95-pdf",_type:"reference"}},pdfHeading:"Download The PDF​​​​‌﻿‍﻿​‍​‍‌‍﻿﻿‌﻿​‍‌‍‍‌‌‍‌﻿‌‍‍‌‌‍﻿‍​‍​‍​﻿‍‍​‍​‍‌﻿​﻿‌‍​‌‌‍﻿‍‌‍‍‌‌﻿‌​‌﻿‍‌​‍﻿‍‌‍‍‌‌‍﻿﻿​‍​‍​‍﻿​​‍​‍‌‍‍​‌﻿​‍‌‍‌‌‌‍‌‍​‍​‍​﻿‍‍​‍​‍‌‍‍​‌﻿‌​‌﻿‌​‌﻿​​​﻿‍‍​‍﻿﻿​‍﻿﻿‌‍﻿​‌‍﻿﻿‌‍​﻿‌‍​‌‌‍﻿​‌‍‍​‌‍﻿﻿‌﻿​﻿‌﻿‌​​﻿‍‍​﻿​﻿​﻿​﻿​﻿​﻿​﻿​﻿​‍﻿﻿‌‍‍‌‌‍﻿‍‌﻿‌​‌‍‌‌‌‍﻿‍‌﻿‌​​‍﻿﻿‌‍‌‌‌‍‌​‌‍‍‌‌﻿‌​​‍﻿﻿‌‍﻿‌‌‍﻿﻿‌‍‌​‌‍‌‌​﻿﻿‌‌﻿​​‌﻿​‍‌‍‌‌‌﻿​﻿‌‍‌‌‌‍﻿‍‌﻿‌​‌‍​‌‌﻿‌​‌‍‍‌‌‍﻿﻿‌‍﻿‍​﻿‍﻿‌‍‍‌‌‍‌​​﻿﻿‌‌‍‌‍‌‍‌​​﻿‌‌​﻿​‌​﻿‌‍​﻿​‍‌‍​‍‌‍​﻿​‍﻿‌​﻿‌‌​﻿​​‌‍​﻿​﻿​﻿​‍﻿‌​﻿‌​​﻿​​‌‍‌‌‌‍​‍​‍﻿‌‌‍​‌‌‍‌‌‌‍​‍​﻿‌‌​‍﻿‌​﻿‌​​﻿‌﻿‌‍‌‌​﻿‌​​﻿​​‌‍‌​​﻿​‌‌‍‌‌​﻿‍‌‌‍​‌​﻿‍​​﻿​‍​﻿‍﻿‌﻿‌​‌﻿‍‌‌﻿​​‌‍‌‌​﻿﻿‌‌‍​﻿‌‍​‌‌﻿​﻿‌‍‌‌‌‌​﻿‌﻿‌​‌﻿‌‌‌‍‌​‌﻿‍‌​﻿‍﻿‌﻿​​‌‍​‌‌﻿‌​‌‍‍​​﻿﻿‌‌﻿​​‌‍‌​‌‍‌‍‌​‍​‌‍‌‌‌‍​‌‌‍‌​‌‍‍‌‌‍﻿‍‌‍‌﻿​﻿﻿﻿‌‍​‍‌‍​‌‌﻿​﻿‌‍‌‌‌‌‌‌‌﻿​‍‌‍﻿​​﻿﻿‌‌‍‍​‌﻿‌​‌﻿‌​‌﻿​​​‍‌‌​﻿​﻿‌​​‌​‍‌‌​﻿​‍‌​‌‍​‍‌‌​﻿​‍‌​‌‍‌‍﻿​‌‍﻿﻿‌‍​﻿‌‍​‌‌‍﻿​‌‍‍​‌‍﻿﻿‌﻿​﻿‌﻿‌​​‍‌‌​﻿​﻿‌​​‌​﻿​﻿​﻿​﻿​﻿​﻿​﻿​﻿​‍‌‍‌‍‍‌‌‍‌​​﻿﻿‌‌‍‌‍‌‍‌​​﻿‌‌​﻿​‌​﻿‌‍​﻿​‍‌‍​‍‌‍​﻿​‍﻿‌​﻿‌‌​﻿​​‌‍​﻿​﻿​﻿​‍﻿‌​﻿‌​​﻿​​‌‍‌‌‌‍​‍​‍﻿‌‌‍​‌‌‍‌‌‌‍​‍​﻿‌‌​‍﻿‌​﻿‌​​﻿‌﻿‌‍‌‌​﻿‌​​﻿​​‌‍‌​​﻿​‌‌‍‌‌​﻿‍‌‌‍​‌​﻿‍​​﻿​‍​‍‌‍‌﻿‌​‌﻿‍‌‌﻿​​‌‍‌‌​﻿﻿‌‌‍​﻿‌‍​‌‌﻿​﻿‌‍‌‌‌‌​﻿‌﻿‌​‌﻿‌‌‌‍‌​‌﻿‍‌​‍‌‍‌﻿​​‌‍​‌‌﻿‌​‌‍‍​​﻿﻿‌‌﻿​​‌‍‌​‌‍‌‍‌​‍​‌‍‌‌‌‍​‌‌‍‌​‌‍‍‌‌‍﻿‍‌‍‌﻿​‍​‍‌﻿﻿‌​​​​‌﻿‍﻿​‍​‍‌‍﻿﻿‌﻿​‍‌‍‍‌‌‍‌﻿‌‍‍‌‌‍﻿‍​‍​‍​﻿‍‍​‍​‍‌﻿​﻿‌‍​‌‌‍﻿‍‌‍‍‌‌﻿‌​‌﻿‍‌​‍﻿‍‌‍‍‌‌‍﻿﻿​‍​‍​‍﻿​​‍​‍‌‍‍​‌﻿​‍‌‍‌‌‌‍‌‍​‍​‍​﻿‍‍​‍​‍‌‍‍​‌﻿‌​‌﻿‌​‌﻿​​​﻿‍‍​‍﻿﻿​‍﻿﻿‌‍﻿​‌‍﻿﻿‌‍​﻿‌‍​‌‌‍﻿​‌‍‍​‌‍﻿﻿‌﻿​